items.completion:
if (file_count > 10000) {
    if (user_balance < 1000) {
        // Send a message to the user
        message = "You have less than 1000 balance. You can still pay but you will be charged extra. Please confirm."
        // Ask the user to confirm
        confirm = await askForConfirmation(message)
        if (!confirm) {
            // If the user doesn't confirm, don't delete the file
            return false
        }
    }
    // If the user has more than 1000 balance, just charge them extra
    message = "You have more than 1000 balance. You will be charged extra. Please confirm."
    confirm = await askForConfirmation(message)
    if (!confirm) {
        // If the user doesn't confirm, don't delete the file
        return false
    }
}
